// Some portions generated by Claude

// @ts-check
const path = require('node:path');
const { test, expect } = require('@playwright/test');

// Millions of results are taller than the browser can scroll, so the rows scroll in their own box in compressed
// coordinates while a slow row store reads each visible window back. No server is needed: the page runs the compiled
// result renderer (npm run build:classic in tools/workbench) over two million generated rows.
const workbenchRoot = path.resolve(__dirname, '../../tools/workbench');
const ORIGIN = 'http://compressed-results.test';
const ROW_COUNT = 2000000;
const READ_LATENCY_MS = 25;

// The page and the Workbench files it loads, served from the working tree: the styles from the front-end sources, the
// compiled scripts from target/frontend.
const files = {
	'/styles/workbench-refresh.css': path.join(workbenchRoot, 'src/main/frontend/static/styles/workbench-refresh.css'),
	'/styles/query.css': path.join(workbenchRoot, 'src/main/frontend/static/styles/query.css'),
	'/scripts/template.js': path.join(workbenchRoot, 'target/frontend/scripts/template.js'),
	'/scripts/queryStream.js': path.join(workbenchRoot, 'target/frontend/scripts/queryStream.js')
};
const pageHtml = above => '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Compressed results</title>'
	+ '<link rel="stylesheet" href="/styles/workbench-refresh.css"><link rel="stylesheet" href="/styles/query.css">'
	+ '<script>var workbench = {};</script><script src="/scripts/template.js"></script>'
	+ '<script src="/scripts/queryStream.js"></script></head>'
	+ '<body class="workbench-body"><main id="content" class="workbench-main">'
	+ `<div id="workbench-page-surface" class="workbench-page-surface"><div style="height: ${above}px">Editor</div>`
	+ '<section id="query-results" class="query-results"></section></div></main></body></html>';

/**
 * Opens a result of rowCount generated rows (ROW_COUNT when absent) in layout, below an editor `above` px tall (400 when
 * absent). With expectElement (the default) it checks that the rows scroll in their own box.
 */
async function openResult(page, layout, { rowCount = ROW_COUNT, above = 400, expectElement = true } = {}) {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.route(`${ORIGIN}/**`, route => {
		const pathname = new URL(route.request().url()).pathname;
		if (pathname === '/') {
			return route.fulfill({ contentType: 'text/html', body: pageHtml(above) });
		}
		return files[pathname] ? route.fulfill({ path: files[pathname] }) : route.fulfill({ status: 404, body: '' });
	});
	await page.goto(`${ORIGIN}/`);
	await page.evaluate(async ({ layout, rowCount, latency }) => {
		const row = index => [
			{ kind: 'iri', value: 'http://example.org/resource/' + index },
			{ kind: 'iri', value: 'http://www.w3.org/2000/01/rdf-schema#label' },
			{ kind: 'literal', value: 'Value number ' + index }
		];
		const placeholder = row(0);
		window.compressedReads = 0;
		const renderer = new window.workbench.queryStream.QueryResultRenderer(document.getElementById('query-results'), {
			initialLayout: layout, batched: true, requestedLimit: rowCount,
			rowStore: {
				async append() { return rowCount; },
				async read(start, count) {
					window.compressedReads++;
					await new Promise(resolve => setTimeout(resolve, latency));
					const rows = [];
					for (let index = start; index < Math.min(rowCount, start + count); index++) rows.push(row(index));
					return rows;
				},
				async count() { return rowCount; }, async truncate() {}, async dispose() {}
			}
		});
		window.compressedRenderer = renderer;
		renderer.beginBatch(0);
		await renderer.accept({ type: 'head', version: 1 });
		await renderer.accept({ type: 'view', id: 'tuple' });
		await renderer.accept({ type: 'vars', values: ['s', 'p', 'o'] });
		for (let start = 0; start < rowCount; start += 250000) {
			await renderer.accept({ type: 'rows', values: new Array(Math.min(250000, rowCount - start)).fill(placeholder) });
		}
		await renderer.accept({ type: 'end', metadata: { 'total-result-count': rowCount, 'result-offset': 0,
			'result-limit': rowCount, 'result-batch-count': rowCount, 'result-has-more': false,
			'result-next-offset': rowCount } });
	}, { layout, rowCount, latency: READ_LATENCY_MS });
	const scrollport = page.locator(layout === 'table'
		? '#query-results .query-result-table-wrap' : '#query-results .query-result-records');
	if (expectElement) {
		await expect(page.locator('#query-results .query-result-layout')).toHaveAttribute('data-scroll-source', 'element');
	}
	await expect(page.locator('#query-results .query-result-layout')).toHaveAttribute('data-effective-layout', layout);
	await page.evaluate(() => {
		const result = document.querySelector('#query-results .query-result-layout');
		window.scrollTo(0, result.getBoundingClientRect().top + window.scrollY);
	});
	await settled(page);
	return scrollport;
}

/** Waits until no window has been read for a while: the last scroll position is rendered. */
async function settled(page) {
	let previous = -1;
	await expect.poll(async () => {
		const reads = await page.evaluate(() => window.compressedReads);
		const quiet = reads === previous;
		previous = reads;
		return quiet;
	}, { intervals: [400] }).toBe(true);
}

/** The rendered rows or records in the scroll box: index, top relative to the box, height. */
function renderedRows(scrollport) {
	return scrollport.evaluate(box => {
		const attribute = box.matches('.query-result-records') ? 'data-query-record-index' : 'data-query-row-index';
		const boxTop = box.getBoundingClientRect().top;
		return Array.from(box.querySelectorAll(`[${attribute}]`)).map(element => {
			const rectangle = element.getBoundingClientRect();
			return { index: Number(element.getAttribute(attribute)), top: rectangle.top - boxTop, height: rectangle.height,
				visible: rectangle.bottom > boxTop && rectangle.top < boxTop + box.clientHeight };
		});
	});
}

/** The scroll position in rows: the first row in view plus how far it is scrolled out above the box. */
function rowPosition(rows) {
	const first = rows.find(row => row.top + row.height > 0);
	const pitch = rows[rows.indexOf(first) + 1].top - first.top;
	return { position: first.index + (-first.top) / pitch, pitch };
}

for (const layout of ['records', 'table']) {
	test.describe(`${layout} with ${ROW_COUNT} results`, () => {
		test('every wheel step counts while windows are still being read', async ({ page }) => {
			const scrollport = await openResult(page, layout);
			const box = await scrollport.boundingBox();
			await page.mouse.move(box.x + box.width / 2, box.y + 200);
			const before = rowPosition(await renderedRows(scrollport));
			for (let step = 0; step < 20; step++) {
				await page.mouse.wheel(0, 100);
				await page.waitForTimeout(10);
			}
			await settled(page);
			const after = rowPosition(await renderedRows(scrollport));
			const expected = 2000 / before.pitch;
			expect(after.position - before.position,
				`20 wheel steps of 100 px should move about ${expected.toFixed(1)} rows of ${before.pitch} px`)
				.toBeGreaterThan(expected * 0.85);
			expect(after.position - before.position).toBeLessThan(expected * 1.15);
		});

		test('a fast drag to the end stays at the end', async ({ page }) => {
			const scrollport = await openResult(page, layout);
			for (let step = 1; step <= 20; step++) {
				await scrollport.evaluate((element, fraction) => {
					element.scrollTop = (element.scrollHeight - element.clientHeight) * fraction;
				}, 0.5 + step / 40);
				await page.waitForTimeout(16);
			}
			await settled(page);
			const end = await scrollport.evaluate(element => ({ scrollTop: element.scrollTop,
				maximum: element.scrollHeight - element.clientHeight }));
			// Within the few pixels a browser can round a scroll position of tens of millions of pixels by.
			expect(end.scrollTop, 'the scroll bar stays where the drag ended').toBeGreaterThanOrEqual(end.maximum - 8);
			const last = (await renderedRows(scrollport)).find(row => row.index === ROW_COUNT - 1);
			expect(last && last.visible, 'the last result is in view').toBe(true);
		});

		test('scroll keys from a focused link inside the rows page by the rows', async ({ page }) => {
			const scrollport = await openResult(page, layout);
			await toMiddle(page, scrollport);
			const view = await scrollport.evaluate(element => element.clientHeight);
			for (const key of ['PageDown', 'Space']) {
				// Tab would focus a link of a row in view; the key then reaches the box from inside it.
				await scrollport.evaluate(element => {
					const top = element.getBoundingClientRect().top;
					Array.from(element.querySelectorAll('a')).find(link => link.getBoundingClientRect().top > top + 40).focus();
				});
				const before = rowPosition(await renderedRows(scrollport));
				const oneView = view / before.pitch;
				await page.keyboard.press(key);
				await settled(page);
				const after = rowPosition(await renderedRows(scrollport));
				expect(after.position - before.position, `${key} from a focused link should move about one view`)
					.toBeGreaterThan(oneView * 0.8);
				expect(after.position - before.position).toBeLessThan(oneView * 1.2);
			}
		});

		test('Space and Shift+Space page by one view', async ({ page }) => {
			const scrollport = await openResult(page, layout);
			await toMiddle(page, scrollport);
			await scrollport.focus();
			const view = await scrollport.evaluate(element => element.clientHeight);
			const before = rowPosition(await renderedRows(scrollport));
			const oneView = view / before.pitch;
			await page.keyboard.press('Space');
			await settled(page);
			const down = rowPosition(await renderedRows(scrollport));
			expect(down.position - before.position, `Space should move about one view (${oneView.toFixed(1)} rows)`)
				.toBeGreaterThan(oneView * 0.8);
			expect(down.position - before.position).toBeLessThan(oneView * 1.2);
			await page.keyboard.press('Shift+Space');
			await settled(page);
			const up = rowPosition(await renderedRows(scrollport));
			expect(Math.abs(up.position - before.position), 'Shift+Space should move back one view').toBeLessThan(0.5);
		});
	});

	// Chromium synthesizes a real touch swipe (with native scrolling) through the DevTools protocol.
	test.describe(`${layout} with ${ROW_COUNT} results on a touch screen`, () => {
		test.use({ hasTouch: true });
		test.skip(({ browserName }) => browserName !== 'chromium', 'touch gestures are synthesized through Chromium');

		test('a swipe moves the rows by the distance of the finger', async ({ page }) => {
			const scrollport = await openResult(page, layout);
			await toMiddle(page, scrollport);
			const before = rowPosition(await renderedRows(scrollport));
			const box = await scrollport.boundingBox();
			const session = await page.context().newCDPSession(page);
			await session.send('Input.synthesizeScrollGesture', { x: Math.round(box.x + box.width / 2),
				y: Math.round(box.y + box.height / 2), yDistance: -300, speed: 800, gestureSourceType: 'touch',
				preventFling: true });
			await settled(page);
			const after = rowPosition(await renderedRows(scrollport));
			const moved = (after.position - before.position) * before.pitch;
			// The browser's touch slop and rounding add a little to the 300 px the finger travels.
			expect(moved, 'a 300 px swipe should move the rows about 300 px').toBeGreaterThan(250);
			expect(moved).toBeLessThan(400);
			await page.waitForTimeout(800);
			const later = rowPosition(await renderedRows(scrollport));
			expect(Math.abs(later.position - after.position), 'the rows stay put once the swipe has settled')
				.toBeLessThan(0.05);
		});
	});
}

// A result that the browser could scroll with the page by itself, below an editor so tall that the page around it would be
// taller than the browser can lay out: its last rows were stacked on one another and out of reach.
test('the last rows of a result just under the scroll capacity stay reachable below a tall page', async ({ page }) => {
	await openResult(page, 'table', { rowCount: 1000, expectElement: false });
	const measured = await page.evaluate(() => {
		const rows = document.querySelectorAll('#query-results [data-query-row-index]');
		return { capacity: window.compressedRenderer.tableScrollCapacity,
			pitch: rows[1].getBoundingClientRect().top - rows[0].getBoundingClientRect().top,
			header: document.querySelector('#query-results thead').getBoundingClientRect().height };
	});
	// Rows that fit the browser's scroll capacity by 2000 px, so on their own they would scroll with the page.
	const rowCount = Math.floor((measured.capacity - measured.header - 2000) / measured.pitch);
	const tall = await page.context().newPage();
	await openResult(tall, 'table', { rowCount, above: 8000, expectElement: false });
	for (let turn = 0; turn < 4; turn++) {
		await tall.evaluate(() => {
			const element = document.querySelector('#query-results .query-result-layout')
				.getAttribute('data-scroll-source') === 'element' ? document.querySelector('#query-results .query-result-table-wrap') : null;
			if (element) {
				element.scrollTop = element.scrollHeight;
			} else {
				window.scrollTo(0, document.documentElement.scrollHeight);
			}
		});
		await settled(tall);
	}
	const end = await tall.evaluate(count => {
		const rows = Array.from(document.querySelectorAll('#query-results [data-query-row-index]'));
		const last = rows.find(row => Number(row.getAttribute('data-query-row-index')) === count - 1);
		const tops = rows.slice(-6).map(row => Math.round(row.getBoundingClientRect().top));
		return { tops, distinctTops: new Set(tops).size, lastVisible: !!last
			&& last.getBoundingClientRect().bottom > 0 && last.getBoundingClientRect().top < window.innerHeight };
	}, rowCount);
	expect(end.distinctTops, `the last rows must not lie on one another: ${end.tops}`).toBe(6);
	expect(end.lastVisible, 'the last result is in view').toBe(true);
});

/** Scrolls the box to the middle of the result, where the scroll bar is compressed the most. */
async function toMiddle(page, scrollport) {
	await scrollport.evaluate(element => {
		element.scrollTop = (element.scrollHeight - element.clientHeight) / 2;
	});
	await settled(page);
}
